'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={studio:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',assets:'<rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="8" cy="8" r="1"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',templates:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',workflows:'<rect x="3" y="3" width="6" height="6" rx="2"/><rect x="15" y="15" width="6" height="6" rx="2"/><path d="M9 6h7v9M6 9v9h9"/>',jobs:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8M8 12h8M8 16h5"/>',compare:'<rect x="3" y="4" width="7" height="16" rx="2"/><rect x="14" y="4" width="7" height="16" rx="2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="white"/><circle cx="15" cy="17" r="3" fill="white"/>',plus:'<path d="M12 5v14M5 12h14"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',shirt:'<path d="m8 4-5 3 2 6 3-1v8h8v-8l3 1 2-6-5-3c-1 3-7 3-8 0Z"/>',pants:'<path d="M6 3h12l2 18h-6l-2-12-2 12H4Z"/><path d="M6 6h12"/>',shoe:'<path d="M4 9c4 5 9 7 15 7v4H3V9Z"/>',person:'<circle cx="12" cy="5" r="3"/><path d="M8 10h8l2 7h-3l1 6h-4l-1-6-1 6H6l1-6H4Z"/>',play:'<path d="m9 5 11 7-11 7Z"/>',check:'<path d="m5 12 4 4L19 6"/>',link:'<path d="M10 14 14 10m-5 6-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>'};
const icon=(id)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.studio}</svg>`;
const pages={studio:'创作台',assets:'素材库',templates:'模板与提示词',workflows:'技能与工作流',jobs:'测试记录',compare:'结果对比',settings:'平台连接'};
const statuses={queued:['排队中','neutral'],submitting:['正在提交','orange'],polling:['生成中','blue'],saving:['保存中','blue'],succeeded:['已保存','green'],failed:['失败','red'],uncertain:['待核对','orange'],paused:['暂停查询','orange'],save_failed:['保存失败','red']};
const badge=(state)=>{const s=statuses[state]||[state,'neutral'];return `<span class="pill ${s[1]}">${esc(s[0])}</span>`};
const money=(v)=>v===null||v===undefined?'待核对':`¥${Number(v).toFixed(6).replace(/0+$/,'').replace(/\.$/,'.00')}`;
const date=t=>new Date(t*1000).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const state={boot:null,assets:[],jobs:[],route:'studio',csrf:'',activeJob:null,loopVideos:false,compareCandidate:'',compare:[],filters:{},draft:{kind:'image',model_id:'seedream',template_id:'studio-front',refs:[],mode:'mock',resolution:'2K',duration:3,ratio:'9:16',seed:42,prompt_override:'',person_mode:'default',identity_consent:false,image_confirmed:false,paid_confirmed:false,reference_board:false,video_mode:'auto',audio_mode:'off',max_cost:3,label:'',group:'',mock_failure:'none'}};
let creating=false,submittingId=null,lastPayload=null,refreshBusy=false;
async function api(path,options={}){const opts={...options,headers:{...options.headers}};if(opts.method&&opts.method!=='GET'){opts.headers['X-Lab-CSRF']=state.csrf;if(!(opts.body instanceof FormData))opts.headers['Content-Type']='application/json';}const r=await fetch('/api'+path,opts);let d;try{d=await r.json()}catch{throw Error('服务器响应无法读取')}if(!r.ok){if(r.status===401)showLogin();throw Error(typeof d.detail==='string'?d.detail:'请求参数不符合要求')}return d}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),6000)}
function showLogin(){$('#shell').classList.add('hidden');$('#login').classList.remove('hidden')}
async function boot(){try{state.boot=await api('/bootstrap');state.csrf=state.boot.csrf;await loadData();$('#login').classList.add('hidden');$('#shell').classList.remove('hidden');renderNav();route();}catch(e){if(!$('#login').classList.contains('hidden'))return;showLogin();$('#login-error').textContent=e.message}}
async function loadData(){const [a,j]=await Promise.all([api('/assets'),api('/jobs')]);state.assets=a;state.jobs=j;}
function renderNav(){$('#nav').innerHTML=Object.entries(pages).map(([k,v])=>`<a href="#${k}" class="nav-item ${state.route===k?'active':''}" data-route="${k}">${icon(k)}<span>${v}</span></a>`).join('')}
function route(){let r=location.hash.slice(1)||'studio';if(!pages[r])r='studio';state.route=r;$('#page-title').textContent=pages[r];renderNav();$('.sidebar').classList.remove('open');render();}
function render(){if(!state.boot)return;({studio:renderStudio,assets:renderAssets,templates:renderTemplates,workflows:renderWorkflows,jobs:renderJobs,compare:renderCompare,settings:renderSettings}[state.route])();}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${subtitle}</p></div><div class="row-actions">${actions}</div></div>`}
function currentModel(){return state.boot.models.find(m=>m.id===state.draft.model_id)}
function currentTemplate(){return state.boot.templates.find(t=>t.id===state.draft.template_id)}
function asset(id){return state.assets.find(a=>a.id===id)}
function media(a,cls='',controls=false){if(a?.kind==='audio')return `<audio class="${cls}" src="${esc(a.url)}" controls preload="metadata"></audio>`;if(a?.kind==='file')return `<div class="file-preview">${icon('assets')}<span>${esc(a.name)}</span></div>`;if(!a)return '';return a.kind==='video'?`<video class="${cls}" src="${esc(a.url)}" ${controls?'controls':''} ${controls&&state.loopVideos?'loop':''} playsinline preload="metadata"></video>`:`<img class="${cls}" src="${esc(a.url)}" alt="${esc(a.name)}" loading="lazy">`}

const unitName=u=>u==='tokens'?'计费Token':u==='credits'?'积分':'无Token计费';
const unitCount=n=>n===null||n===undefined?'—':Number(n).toLocaleString('zh-CN',{maximumFractionDigits:6});
function loopControl(){return `<label class="checkbox playback-toggle"><input type="checkbox" data-loop ${state.loopVideos?'checked':''}>循环播放</label>`}
function reportedUsage(j){const names={total_tokens:'总Token',input_tokens:'输入Token',output_tokens:'输出Token',prompt_tokens:'输入Token',completion_tokens:'输出Token',credits:'积分',generated_images:'图片数'};return Object.entries(j.reported_usage||{}).map(([k,v])=>`<span>供应商回传${names[k]||esc(k)} ${unitCount(v)}（未对账）</span>`).join('')}
function costSummary(j){const b=j.review?.billing;return `${reportedUsage(j)}<strong>费用 ${money(j.actual)}</strong><span>${b?.cost_source==='units_calculated'?'由实填用量计算':j.actual===null?'账单待核对':j.body.mode==='mock'?'模拟零费用':'已填账单金额'}</span>${b?.actual_units!==null&&b?.actual_units!==undefined?`<span>${unitName(b.unit)} ${unitCount(b.actual_units)} · 实填</span>`:b?.inferred_units!==null&&b?.inferred_units!==undefined?`<span>${unitName(b.unit)} ${unitCount(b.inferred_units)} · 金额反推</span>`:''}`}
function fileSpec(a){if(!a)return '';let d={};try{d=JSON.parse(a.details||'{}')}catch{}return `${a.width&&a.height?`${a.width} × ${a.height}px`:'无画面尺寸'}${a.duration?` · ${Number(a.duration).toFixed(2)}s`:''} · ${(a.size/1048576).toFixed(2)} MiB · ${esc(a.mime)}${d.codec?` · ${esc(d.codec)}`:''}${d.fps?` · ${Number(d.fps.toFixed(2))}fps`:''}`}
function issueButtons(j){const issues=['非白背景','杂物残留','印花变化','服装变形','漏单品','身份漂移','构图变化','头脚截断','模糊',...(j.body.kind==='video'?['闪烁','动作突变','旋转不完整','接缝跳变']:[])];return `<div class="issue-options">${issues.map(x=>`<button type="button" class="issue-chip ${(j.review?.issues||[]).includes(x)?'selected':''}" data-issue="${esc(x)}">${esc(x)}</button>`).join('')}</div>`}
function jobTags(j,a=asset(j.outputs?.[0])){const b=j.body,m=b.model_snapshot;return `<div class="evaluation-tags"><span class="pill blue">${esc(providerName(m.provider))}</span><span class="pill neutral">${esc(m.name)}</span><span class="pill ${b.mode==='mock'?'neutral':'orange'}">${b.mode==='mock'?'模拟结果':'真实AI生成'}</span><span class="pill neutral">选定 ${esc(b.resolution)}</span>${b.kind==='video'?`<span class="pill neutral">请求 ${b.duration}s</span>`:''}<span class="pill neutral">画幅 ${esc(b.ratio)}</span><span class="pill neutral">${esc(m.modes?.[b.video_mode]?.label||b.video_mode)}</span>${b.kind==='video'?`<span class="pill neutral">${{off:'静音',native:'模型声音',original:'原声'}[b.audio_mode]||'静音'}</span>`:''}<span class="pill neutral">${esc(b.template_snapshot?.name||b.template_id)} v${b.template_version}</span></div>${a?`<p class="file-spec">实际文件 ${fileSpec(a)}</p>`:''}`}
function assetProvenance(a){const p=a.provenance||{type:a.source==='demo'?'demo':'upload'},labels={generated:'AI生成',mock_generated:'模拟结果',upload:'上传素材',demo:'示例素材'};if(!p.job_id)return `<span class="pill neutral">${p.type==='upload'?({self:'本人上传',user:'用户提供',unknown:'上传来源未标记'}[p.upload_origin]||'上传来源未标记'):labels[p.type]||'来源待核对'}</span><p class="small-note">${p.type==='unknown'?'来源待核对；费用与Token未知':'本站生成费用不适用 · 计费Token不适用'}</p>`;const j={body:{mode:p.type==='mock_generated'?'mock':'live'},review:{billing:p.billing},actual:p.actual_cny,reported_usage:p.reported_usage};return `<div class="evaluation-tags"><span class="pill ${p.type==='generated'?'orange':'neutral'}">${labels[p.type]}</span><span class="pill blue">${esc(providerName(p.provider))}</span><span class="pill neutral">${esc(p.model_name)}</span><span class="pill neutral">选定 ${esc(p.resolution)}</span>${p.duration?`<span class="pill neutral">请求 ${p.duration}s</span>`:''}</div><div class="cost-detail">${costSummary(j)}</div><p class="small-note">模型 ${esc(p.model)}<br>${esc(p.template_id)} v${p.template_version} · ${esc(p.ratio)}</p><button class="text-button" data-job="${p.job_id}">来源任务 / 评分 ↗</button>`}
function scoreRow(j){return `<div class="score-row">${[['clothing','服装'],['identity','身份'],...(j.body.kind==='video'?[['motion','动作']]:[]),['background','白底'],['framing','构图'],['detail','细节']].map(([k,n])=>`<span>${n} ${j.review?.[k]||'—'}/5</span>`).join('')}</div>`}
function compareCandidate(){const root=$('#compare-candidate');if(!root)return;const j=state.jobs.find(x=>x.id===state.compareCandidate);root.innerHTML=j?`<div class="candidate-layout"><div class="asset-image">${media(asset(j.outputs[0]),'',true)}</div><div><h3>${esc(j.body.label||j.body.model_snapshot.name)}</h3>${jobTags(j)}<div class="cost-detail">${costSummary(j)}</div><button class="button primary" data-add-compare="${j.id}" ${state.compare.includes(j.id)||state.compare.length>=4?'disabled':''}>加入对比</button></div></div>`:'<p class="hint">先选择一条结果，在这里播放或查看图片，再决定是否加入对比。</p>'}
function billingFields(j){const r=j.review||{},b=r.billing||{},c=j.billing_context;return `<section class="billing-panel full"><h3>账单金额与计费用量</h3><p class="hint">当前渠道：${esc(providerName(j.body.model_snapshot.provider))} · ${esc(j.body.model_snapshot.model)}<br>${c.unit?`${unitName(c.unit)}单价 ${c.rate??'待确认'} 元 / ${unitCount(c.rate_basis)} ${unitName(c.unit)}`:'官方按秒、张或次计费；不能凭空反推Token。需要时填写账单提供的Token单价。'} · 核对日期 ${esc(c.date||'待核对')}<br><a href="${esc(c.source||'#')}" target="_blank" rel="noreferrer">官方价格 ↗</a>${c.verification==='previous_profile'?'<br>沿用既有价格档案，本次官方页面未完整复核，请与账户实际单价核对。':c.verification==='historical_missing'?'<br>历史任务没有计费单价快照，请按当时账单填写单价与依据。':''}</p><div class="review-form"><div class="field"><label>核对方式</label><select name="billing_mode" ${j.body.mode==='mock'?'disabled':''}>${[['amount','填写账单金额'],['units','填写计费用量 → 算金额'],['both','同时填写金额与用量']].map(([k,n])=>`<option value="${k}" ${(r.billing_mode||'amount')===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>用量单位</label><select name="billing_unit">${options(['tokens','credits'],r.billing_unit||b.unit||c.unit||'tokens').replace('>tokens<','>计费Token<').replace('>credits<','>积分<')}</select></div><div class="field"><label>账单金额（元）</label><input name="actual_cny" type="number" min="0" step="any" value="${j.actual??''}" placeholder="留空表示待核对"></div><div class="field"><label>计费用量（金额模式为反推）</label><input name="billed_units" type="number" min="0" step="any" value="${b.actual_units??b.inferred_units??''}" placeholder="填写账单的计费总量"></div><div class="field"><label>账户实际单价（可选）</label><input name="rate_override" type="number" min="0.000001" step="any" value="${r.rate_override??''}" placeholder="${c.rate??'需填写'}"><small>Token：元/百万Token；积分：元/积分</small></div><div class="field"><label>单价依据 / 折扣说明</label><input name="rate_note" value="${esc(r.rate_note||'')}" placeholder="自定义单价时必填"></div><div class="field full"><label>账单参考编号（可选）</label><input name="bill_reference" value="${esc(r.bill_reference||'')}" placeholder="任务或账单编号，不要填写Key"></div></div><div id="billing-calculation" class="calculation-result" aria-live="polite"></div><p class="hint">刊例参考 ${money(c.reference_cny)} · ${esc(c.breakdown.join('；'))}<br>${esc(c.note||'')}<br>金额反推标为折算用量；按量算出的金额标为计算金额。失败任务仍可登记实际账单。</p></section>`}
let billingTimer,billingSequence=0;
function receiptPayload(f){const d=Object.fromEntries(new FormData(f));const number=k=>d[k]===''||d[k]===undefined?null:Number(d[k]);const mode=d.billing_mode||'amount';return {billing_mode:mode,billing_unit:d.billing_unit||null,actual_cny:mode==='units'?null:number('actual_cny'),billed_units:mode==='amount'?null:number('billed_units'),rate_override:number('rate_override'),rate_note:d.rate_note||'',bill_reference:d.bill_reference||''}}
async function updateBilling(){const f=$('#review-form');if(!f)return;const c=state.reviewContext,mode=f.elements.billing_mode.value;f.elements.actual_cny.readOnly=mode==='units'||state.reviewMock;f.elements.billed_units.readOnly=mode==='amount'||state.reviewMock;const id=++billingSequence;try{const data=await api('/jobs/'+f.dataset.jid+'/billing-preview',{method:'POST',body:JSON.stringify(receiptPayload(f))});if(id!==billingSequence||$('#review-form')!==f)return;if(mode==='amount')f.elements.billed_units.value=data.inferred_units??'';if(mode==='units')f.elements.actual_cny.value=data.actual_cny??'';$('#billing-calculation').textContent=`${data.unit?`${unitName(data.unit)}单价 ${data.rate??'待确认'} 元/${unitCount(data.rate_basis)}；`:''}${mode==='units'?`计算金额 ${money(data.calculated_cny)}`:mode==='both'?`按用量计算 ${money(data.calculated_cny)}；账单差额 ${money(data.difference_cny)}`:data.inferred_units!==null?`金额反推 ${unitCount(data.inferred_units)} ${unitName(data.unit)}（非实测）`:'仅登记金额；不反推Token'}${c.verification==='previous_profile'?'；请核对账户单价':''}`;}catch(e){if(id===billingSequence&&$('#review-form')===f)$('#billing-calculation').textContent=e.message;}}

function options(values,selected){return values.map(v=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(v)}</option>`).join('')}
function field(label,key,type='input',values=[]){const v=state.draft[key];return `<div class="field"><label for="f-${key}">${label}</label>${type==='select'?`<select id="f-${key}" data-field="${key}">${options(values,v)}</select>`:`<input id="f-${key}" data-field="${key}" value="${esc(v)}" ${type==='number'?'type="number" min="0" step="any"':'type="text"'}>`}</div>`}
function check(label,key){return `<label class="checkbox"><input type="checkbox" data-field="${key}" ${state.draft[key]?'checked':''}>${label}</label>`}
function providerName(id){return state.boot.providers.find(p=>p.id===id)?.name||id}
function inputCheck(){return WardrobeInputs.check(currentModel(),state.draft,asset,state.boot.usages)}
function refProposal(ref,d=state.draft,resolve=asset){return WardrobeInputs.propose(currentModel(),d,ref,resolve,state.boot.usages)}
function inputKinds(){return [...new Set(allowedUsages().filter(u=>currentModel().modes[state.draft.video_mode].limits[u]>0).map(WardrobeInputs.kindOfUsage))]}
function canAddKind(kind){if(state.draft.kind==='image'&&state.draft.reference_board)return kind==='image'&&currentModel().modes[state.draft.video_mode].limits.reference_image>0&&state.draft.refs.length<(currentModel().total_refs||50);const ref={vendor_kind:kind,url:'https://materials.example.com/new-'+kind,role:kind==='image'?'look':'motion',duration:currentModel()[kind+'_min']||1};return !refProposal(ref).error}
function syncParameters(){let opts;for(let n=0;n<2;n++){opts=WardrobeInputs.parameters(currentModel(),state.draft,asset);for(const [key,values] of Object.entries(opts))if(values.length&&!values.some(v=>String(v)===String(state.draft[key])))state.draft[key]=values[0];}return opts;}
function selectionNotice(){const c=inputCheck(),spec=currentModel().modes[state.draft.video_mode];return `<div id="input-status" class="input-status" aria-live="polite"><p>${Object.entries(spec.limits).filter(([,n])=>n>0).map(([u,n])=>`${esc(state.boot.usages[u])} ${c.counts[u]||0} / ${n}`).join(' · ')||'当前模式只接收文字'}</p>${state.draft.reference_board&&state.draft.kind==='image'?'<p>参考板：本地图片合成一张输入；不进行额外AI调用。</p>':''}${[...c.errors.map(x=>x.message),...c.missing].filter((v,i,a)=>a.indexOf(v)===i).map(x=>`<p class="input-error">${esc(x)}</p>`).join('')}</div>`}
function selectionBlocked(){const c=inputCheck();return c.errors.length||c.missing.length||Object.entries(WardrobeInputs.parameters(currentModel(),state.draft,asset)).some(([k,v])=>!v.length&&(k!=='duration'||currentModel().modes[state.draft.video_mode]?.durations?.length||currentModel().durations.length));}
function allowedUsages(){return Object.keys(currentModel().modes[state.draft.video_mode]?.limits||{})}
function refCard(r,i){const a=asset(r.asset_id),issues=inputCheck().errors.filter(x=>x.index===i);return `<div class="ref ${issues.length?'ref-invalid':''}"><div class="ref-preview">${a?media(a):`<div class="file-preview">${icon('link')}<span>${esc(r.vendor_asset_id||'外部'+r.vendor_kind)}</span></div>`}</div><button class="ref-remove" data-remove-ref="${i}" aria-label="移除素材">×</button><small>${esc(a?.name||r.vendor_asset_id||r.url)}</small><select data-role-index="${i}" aria-label="素材语义角色">${Object.entries(state.boot.roles).map(([k,v])=>`<option value="${k}" ${r.role===k?'selected':''}>${esc(v)}</option>`).join('')}</select><select data-ref-key="usage" data-ref-index="${i}" aria-label="接口素材用途">${['auto',...allowedUsages().filter(u=>currentModel().modes[state.draft.video_mode].limits[u]>0&&WardrobeInputs.kindOfUsage(u)===(a?.kind||r.vendor_kind||'image')),...(r.usage&&!allowedUsages().includes(r.usage)&&r.usage!=='auto'?[r.usage]:[])].map(k=>`<option value="${k}" ${r.usage===k||(!r.usage&&k==='auto')?'selected':''}>${esc(state.boot.usages[k])}</option>`).join('')}</select>${state.draft.video_mode==='subjects'?`<input data-ref-key="subject_name" data-ref-index="${i}" aria-label="主体分组名称" placeholder="主体分组名称" value="${esc(r.subject_name||'')}"><input data-ref-key="voice_id" data-ref-index="${i}" placeholder="可选声音ID" value="${esc(r.voice_id||'')}">`:''}${currentModel().voice_binding?`<input data-ref-key="voice_url" data-ref-index="${i}" placeholder="绑定音色HTTPS URL（1～10秒）" value="${esc(r.voice_url||'')}">`:''}${issues.map(x=>`<p class="input-error">${esc(x.message)}</p>`).join('')}</div>`}
function priceInfo(m){const p=m.pricing;if(m.billing?.unit==='tokens')return `${m.billing.rate}元/百万计费Token · `+(p.flat!==undefined?`折合 ¥${p.flat}/${p.type==='second'?'秒':'次'}`:p.type==='vidu_q2'?'按首秒/后续秒分段折算':Object.entries(p.rates||{}).map(([k,v])=>`${k} ¥${v}`).join(' · ')+(p.type==='second'?'/秒':'/次'));if(m.billing?.unit==='credits')return `${m.billing.rate}元/积分`;if(!p||p.type==='unknown')return '费用待账户后台核对';if(p.flat!==undefined)return `¥${p.flat}/${p.type==='second'?'秒':'次'}`;if(p.type==='token')return '按Token计费，参考视频有最低计量';if(p.type==='vidu_q2')return '按模式与首秒/后续秒分段计费';if(p.type==='image_tiers')return '按参考图数量0／1～3／4～7档计费';return Object.entries(p.rates||{}).map(([k,v])=>`${k} ¥${v}`).join(' · ')+(p.type==='second'?'/秒':'/次')}
function capabilityPanel(m){const mode=m.modes[state.draft.video_mode];return `<div class="capability-panel"><div class="timeline-summary"><span class="pill blue">${esc(providerName(m.provider))}</span><span class="pill neutral">${esc(mode?.label)}</span><span class="pill neutral">${m.live_tested?'已真实验证':'待真实调用验证'}</span></div><p class="hint">${Object.entries(mode?.limits||{}).filter(([k,n])=>n>0).map(([k,n])=>`${esc(state.boot.usages[k])} ≤ ${n}`).join(' · ')||'只接收文字，不需要素材'}</p><p class="hint">${esc(m.note)}${m.requires_workspace?' 北京工作空间端点必需：请在服务器配置DASHSCOPE_BASE_URL。':''}</p><p class="hint">图片：${m.min_side}～${m.max_side}px · 单图≤${m.max_mb}MB${m.video_max?`<br>视频：${m.video_min}～${m.video_max}秒 · ≤${m.video_mb}MB${m.video_total?' · 总时长≤'+m.video_total+'秒':''}`:''}${m.audio_max?`<br>音频：${m.audio_min}～${m.audio_max}秒 · ≤${m.audio_mb}MB`:''}</p><p class="hint">刊例 ${esc(priceInfo(m))}${m.pricing?.input_video?'；另计输入视频':''}${m.pricing?.extra_image?'；超额输入图另收费':''}<br>${esc(m.discount_note||'')}<a href="${esc(m.price_source)}" target="_blank" rel="noreferrer">官方价格 ↗</a></p>${m.restricted_identity?'<div class="notice">Seedance真人：先在方舟“体验中心→我的→真人→管理素材”扫码完成本人授权，再填Active Asset ID。原始可信产物URL需来自本人账号规定模型30天内结果；供应商仍会审核。普通自拍直接上传会被拦截。</div>':''}</div>`}
function externalDialog(){dialog('供应商授权素材 / 公网素材',`<form id="external-form"><div class="form-grid"><div class="field full"><label>来源类型</label><select name="source"><option value="url">HTTPS公网URL</option><option value="id">供应商资产ID（方舟/可灵）</option></select></div><div class="field full"><label>URL 或 ID</label><input name="value" required placeholder="https://… 或 asset-…"></div><div class="field"><label>素材类型</label><select name="vendor_kind">${options(inputKinds().filter(canAddKind),inputKinds().filter(canAddKind).includes('image')?'image':inputKinds().filter(canAddKind)[0])}</select></div><div class="field"><label>视频/音频实际时长（秒）</label><input name="duration" type="number" step="0.01" min="0" placeholder="图片留空"></div></div><label class="checkbox"><input name="vendor_active" type="checkbox">我已在供应商后台确认资产为Active、授权未过期</label><label class="checkbox"><input name="trusted_original" type="checkbox">此URL是符合方舟信任要求的本账号30天内原始产物</label><p class="hint">本站不下载外部输入文件；供应商将访问该链接，链接元数据与权限由供应商验证。请勿填入API Key或访问密码。</p><button class="button primary" type="submit">加入素材并选择用途</button></form>`)}
function renderStudio(){const d=state.draft,m=currentModel();if(d.video_mode==='auto')d.video_mode=m.default_mode;const paramOptions=syncParameters(),hasRoom=inputKinds().some(canAddKind);const templates=state.boot.templates.filter(t=>t.kind===d.kind),models=state.boot.models.filter(x=>(x.kind==='image')===(d.kind==='image'));
 $('#main').innerHTML=heading('CREATE SOMETHING PERSONAL','从一套穿搭，开始探索。','把素材、人物与动作放在一起，验证每一种生成可能。',`<button class="button" data-action="demo">${icon('plus')}载入示例素材</button>`)+
 `<section class="hero"><div><p class="eyebrow">YOUR NEXT LOOK</p><h2>先看清穿搭，再让它动起来。</h2><p>保留每一张原图，比较每一个模型，找到值得交付的效果。</p><div class="hero-badges"><span class="pill orange">${icon('assets')} 多素材参考</span><span class="pill neutral">图片确认后生成视频</span><span class="pill neutral">结果可下载</span></div></div><div class="hero-art" aria-hidden="true"><div class="art-card">${icon('shirt')}</div><div class="art-card">${icon('person')}</div><div class="art-card">${icon('shoe')}</div></div></section>`+
 `<div class="studio-grid"><section class="card"><div class="segmented"><button class="segment ${d.kind==='image'?'active':''}" data-kind="image">穿搭 / 商品图</button><button class="segment ${d.kind==='video'?'active':''}" data-kind="video">动态展示</button></div>
 <div class="card-head"><div><h3><span class="step-number">01</span>选择展示模板</h3><p>让构图与动作有一个稳定的起点。</p></div><a href="#templates" class="text-button">管理模板 ↗</a></div>
 <div class="template-options">${templates.map(t=>`<button class="template-tile ${d.template_id===t.id?'active':''}" data-template="${esc(t.id)}"><div class="tile-icon">${icon(t.kind==='image'?'person':'play')}<span>${d.template_id===t.id?'✓':'○'}</span></div><strong>${esc(t.name)}</strong><small>${esc(t.description)}</small></button>`).join('')}</div>
 <div class="section-label"><span><span class="step-number">02</span>${d.kind==='image'?'添加人物与衣服素材':'按输入模式添加素材'}</span><span>${d.refs.length} 件</span></div><div class="refs-grid">${d.refs.map(refCard).join('')}<button class="add-ref" data-action="picker" ${hasRoom?'':'disabled'}>${icon('plus')}选择 / 上传素材</button><button class="add-ref" data-action="external" ${hasRoom&&!d.reference_board?'':'disabled'}>${icon('link')}授权ID / 公网URL</button></div>${selectionNotice()}
 <div class="section-label"><span><span class="step-number">03</span>模型与生成参数</span><a href="${esc(m.docs)}" target="_blank" rel="noreferrer" class="text-button">接口文档 ↗</a></div><div class="form-grid"><div class="field full"><label for="f-model_id">平台 / 模型</label><select id="f-model_id" data-field="model_id">${models.map(x=>`<option value="${x.id}" ${m.id===x.id?'selected':''}>${esc(providerName(x.provider)+' · '+x.name)}</option>`).join('')}</select></div><div class="field full"><label for="f-video_mode">输入模式</label><select id="f-video_mode" data-field="video_mode">${Object.entries(m.modes).map(([k,v])=>`<option value="${k}" ${d.video_mode===k?'selected':''}>${esc(v.label)}</option>`).join('')}</select></div>${field(m.kind==='motion'&&m.id==='wan-animate'?'服务模式':'清晰度','resolution','select',paramOptions.resolution)}${d.kind==='video'&&m.durations.length&&d.video_mode!=='edit'?field('生成时长（秒）','duration','select',paramOptions.duration):field('固定随机种子','seed','number')}${d.kind==='video'?field('画幅（首帧类可能随输入）','ratio','select',paramOptions.ratio):field('人物模式','person_mode','select',['default','self'])}${d.kind==='video'?field('输出声音','audio_mode','select',paramOptions.audio_mode):''}${field('本次预算预占（元）','max_cost','number')}</div>
 ${capabilityPanel(m)}
 ${currentTemplate()?.id==='full-turn-360'?'<div class="notice">360°建议8～15秒；请选择支持该时长的模型。固定水平全身机位；仅单张正面图不能证明背面服装细节真实。</div>':''}${d.kind==='video'?'<p class="hint">白底展示建议使用已确认的白底全身首帧。提示词不能保证去除原背景；动作迁移等不接收提示词的接口需要白底输入或支持背景替换的专用模式。</p>':''}<div class="section-label"><span>提示词与技能配置</span><button class="text-button" data-action="reset-prompt">恢复模板提示词</button></div><textarea data-field="prompt_override" aria-label="提示词" placeholder="${esc(currentTemplate()?.prompt||'')}">${esc(d.prompt_override)}</textarea><p class="hint">留空使用模板 v${currentTemplate()?.version}。素材顺序说明由工作流自动追加；万相动作迁移忽略此项。</p>
 ${d.kind==='image'?check('使用参考板进行生图对照（普通图片处理，无额外 AI 调用）','reference_board'):check('我已检查这张穿搭图，确认用于动态展示','image_confirmed')}
 ${check('本人参考素材已获得授权（默认模特无需提供自拍）','identity_consent')}
 <div class="form-grid section-label">${field('实验名称（可选）','label')}${field('对照组标签（可选）','group')}</div>
 <div class="mode-row"><label>执行模式</label><select data-field="mode"><option value="mock" ${d.mode==='mock'?'selected':''}>模拟 · 零模型费用</option><option value="live" ${d.mode==='live'?'selected':''}>真实 · 产生 API 费用</option></select></div>
 ${d.mode==='live'?`<div class="notice">真实调用需服务器开启并配置 Key。预算预占控制本站新任务，不能替代供应商账单上限。</div>${check('确认本次真实调用及可能产生的费用','paid_confirmed')}`:`<p class="hint">模拟输出为流程验证素材，视频是静态帧，不用于评估模型效果。</p>`}
 <details><summary class="small-note">模拟故障测试</summary><select class="dialog-input" data-field="mock_failure">${options(['none','generation','submit_unknown','save_once'],d.mock_failure)}</select><p class="hint">分别验证正常、生成失败、提交不确定与保存失败续接。</p></details>
 <div class="submit-row"><button class="button" data-action="preview">预览请求</button><button class="button primary" data-action="generate" ${creating||selectionBlocked()?'disabled':''}>${icon('studio')}${creating?'正在提交…':d.mode==='mock'?'运行模拟流程':'开始真实生成'}</button></div></section>
 <aside><section class="card preview-card"><div class="preview-header"><h3>Look 预览</h3><span class="pill neutral" id="preview-mode">等待创作</span></div><div id="preview-canvas" class="preview-canvas"></div><div class="preview-footer"><div id="flow" class="flow-line"></div><div class="preview-meta"><span id="preview-model">选定模板与素材后开始</span><span id="preview-cost">零费用模拟可用</span></div><div id="preview-tags"></div><div id="preview-actions"></div></div></section><section class="card recent-bar"><div class="card-head"><h3>最近的实验</h3><a href="#jobs" class="text-button">全部记录 ↗</a></div><div id="recent-jobs"></div></section></aside></div>`;
 updatePreview();updateRecent();}
function updateRecent(){if(!$('#recent-jobs'))return;$('#recent-jobs').innerHTML=state.jobs.slice(0,4).map(j=>`<div class="job-mini"><button class="text-button" data-job="${j.id}">${esc(j.body.label||j.body.model_snapshot.name)}<br><small>${date(j.created)}</small></button>${badge(j.state)}</div>`).join('')||'<p class="small-note">还没有实验。先运行一次模拟流程。</p>'}
function updatePreview(){if(!$('#preview-canvas'))return;const j=state.jobs.find(x=>x.id===state.activeJob);const a=j?.outputs?.length?asset(j.outputs[0]):null;
 const canvas=$('#preview-canvas');
 if(!a||canvas.dataset.asset!==a.id){
  canvas.classList.toggle('has-output',!!a);canvas.dataset.asset=a?.id||'';
  canvas.innerHTML=a?media(a,'output-media',true)+(a.kind==='video'?loopControl()+'<div class="scrub-wrap"><label for="video-scrub">拖动观看 · 已生成视角</label><input id="video-scrub" class="scrubber" type="range" min="0" max="1000" value="0" aria-label="视频展示进度"></div>':''):`<div class="empty-look">${icon('person')}<h3>${j?statuses[j.state]?.[0]:'你的下一套 Look'}</h3><p>${j?esc(j.error||'流程正在后台执行，离开页面也能继续查询。'):'选择模板，加入衣服素材。每一次探索都会留下记录。'}</p></div>`;
  const video=$('video',canvas),scrub=$('#video-scrub');
  if(video&&scrub){scrub.addEventListener('input',()=>{if(Number.isFinite(video.duration))video.currentTime=video.duration*Number(scrub.value)/1000;});video.addEventListener('timeupdate',()=>{if(Number.isFinite(video.duration)&&document.activeElement!==scrub)scrub.value=String(video.currentTime/video.duration*1000);});}
 }
 $('#preview-mode').innerHTML=j?badge(j.state):'等待创作';$('#preview-model').textContent=j?j.body.model_snapshot.name:'选定模板与素材后开始';$('#preview-cost').textContent=j?(j.body.mode==='mock'?'模拟 · ¥0.00':`费用 ${money(j.actual)}`):'零费用模拟可用';
 if($('#preview-tags'))$('#preview-tags').innerHTML=j?jobTags(j,a):'';
 const s=j?.state;const stages=['校验素材','生成结果','保存文件','人工确认'];const index=s==='succeeded'?3:s==='saving'||s==='save_failed'?2:s?1:0;$('#flow').innerHTML=stages.map((x,i)=>`${i?'<span class="flow-connector"></span>':''}<span class="flow-dot ${j&&i<index?'done':j&&i===index?'current':''}"><i>${j&&i<index?'✓':i+1}</i>${x}</span>`).join('');
 $('#preview-actions').innerHTML=j?`<div class="submit-row"><button class="button small" data-job="${j.id}">查看 / 评分</button>${a?`<a class="button small" href="${esc(a.download_url)}">下载结果</a>`:''}${a?.kind==='image'&&j.review?.verdict==='pass'?`<button class="button small primary" data-video-from="${a.id}">生成动态展示</button>`:''}</div>`:'';
}
function renderAssets(){const q=state.filters.assetQuery||'',kind=state.filters.assetKind||'all',source=state.filters.assetSource||'all';const list=state.assets.filter(a=>(kind==='all'||a.kind===kind)&&(source==='all'||a.provenance?.type===source||a.provenance?.type==='upload'&&a.provenance?.upload_origin===source)&&`${a.name} ${a.provenance?.model_name||''} ${a.provenance?.model||''} ${a.provenance?.resolution||''}`.toLowerCase().includes(q.toLowerCase()));$('#main').innerHTML=heading('YOUR SOURCE MATERIAL','每一件素材，都值得保留。','区分用户上传、AI生成、模拟与示例；生成结果关联原始测试任务。',`<button class="button primary" data-action="picker">${icon('upload')}上传素材</button>`)+`<div class="toolbar"><input id="asset-search" placeholder="搜索名称、模型或清晰度" value="${esc(q)}" aria-label="搜索素材"><select id="asset-kind" aria-label="素材类型">${[['all','全部素材'],['image','图片'],['video','视频'],['audio','音频'],['file','文档']].map(([k,n])=>`<option value="${k}" ${kind===k?'selected':''}>${n}</option>`).join('')}</select><select id="asset-source" aria-label="素材来源">${[['all','全部来源'],['upload','全部上传'],['self','本人上传'],['user','用户提供'],['unknown','上传来源未标记'],['generated','AI生成'],['mock_generated','模拟结果'],['demo','示例素材']].map(([k,n])=>`<option value="${k}" ${source===k?'selected':''}>${n}</option>`).join('')}</select>${loopControl()}<span class="pill neutral">${list.length} 件</span></div>`+(list.length?`<div class="asset-grid">${list.map(a=>`<article class="asset-tile"><div class="asset-image">${media(a,'',a.kind==='video')}</div><div class="asset-info"><h3 title="${esc(a.name)}">${esc(a.name)}</h3><p class="file-spec">实际文件 ${fileSpec(a)}</p>${assetProvenance(a)}<details class="asset-details"><summary>文件详情</summary><p>保存时间 ${esc(new Date(a.created*1000).toLocaleString('zh-CN'))}<br>文件大小 ${unitCount(a.size)} 字节<br>SHA256 ${esc(a.sha256)}</p></details><div class="asset-actions"><a class="button small" href="${esc(a.download_url)}">下载</a><button class="button small" data-use-asset="${a.id}">用作素材</button><button class="button small danger" data-delete-asset="${a.id}">删除</button></div></div></article>`).join('')}</div>`:empty('assets','没有符合条件的素材','上传素材，或调整来源与类型筛选。'))}
function empty(i,title,desc){return `<div class="empty-state">${icon(i)}<h3>${title}</h3><p>${desc}</p></div>`}
function renderTemplates(){$('#main').innerHTML=heading('TEMPLATES & PROMPTS','为创作，建立稳定的起点。','提示词与验收规则按版本保存，旧实验始终保留原配置。',`<button class="button primary" data-edit-template="new">${icon('plus')}新建模板</button>`)+`<div class="grid3">${state.boot.templates.map(t=>`<article class="card template-card"><div class="template-preview">${icon(t.kind==='image'?'person':'play')}</div><div class="card-head"><h3>${esc(t.name)}</h3><span class="pill neutral">v${t.version}</span></div><p>${esc(t.description)}</p><div class="timeline-summary"><span class="pill ${t.kind==='image'?'orange':'blue'}">${t.kind==='image'?'图片':'视频'}</span><span class="pill neutral">${esc(t.category)}</span></div><div class="row-actions"><button class="button small" data-edit-template="${t.id}">编辑与版本</button><button class="button small" data-template-use="${t.id}">使用模板 ↗</button></div></article>`).join('')}</div><div class="notice">模板只提供约束与参考，不保证每次一致。若需要姿势图或动作视频，请在素材库上传有使用授权的实际素材。</div>`}
function renderWorkflows(){$('#main').innerHTML=heading('SKILLS & WORKFLOWS','让每一步，都清晰可控。','固定编排不额外消耗规划模型。图片与视频之间保留人工确认。')+`<div class="card"><div class="card-head"><div><h2>穿搭图 → 动态展示</h2><p>工作流 v1.0 · 后端执行，任务状态持久化。</p></div><span class="pill green">可运行模拟测试</span></div><div class="workflow-stages">${[['input_validate','校验素材',false],['outfit_image','多图穿搭',true],['asset_finalize','保存图片',false],['human_review','用户确认',false],['outfit_video','动态展示',true],['asset_finalize','保存与评分',false]].map(([id,n,ai],i)=>`<div class="workflow-stage ${ai?'ai':''}"><span class="pill ${ai?'orange':'neutral'}">${ai?'AI 调用':'固定规则'}</span><strong>${String(i+1).padStart(2,'0')} ${n}</strong><small>${id}</small></div>`).join('')}</div><p class="hint">图片和视频为关联的独立任务。视频失败复用图片，保存失败只重新保存；生成提交异常进入待核对，禁止自动重提。</p><div class="row-actions"><a class="button" href="#studio">测试工作流 ↗</a><a class="button" href="#templates">编辑模板与提示词</a></div></div><div class="notice blue">工作流由我们的服务器执行，GitHub Actions 只负责程序部署。任务恢复、预算记录和素材隐私由后端统一管理。</div><div class="grid3">${state.boot.skills.map(s=>`<article class="skill-tile"><div class="card-head"><h3>${esc(s.name)}</h3><span class="pill ${s.deferred?'neutral':s.ai?'orange':'green'}">${s.deferred?'后续':s.ai?'模型生成':'规则执行'}</span></div><code>${s.id}</code><p>${esc(s.description)}</p></article>`).join('')}</div>`}
function metrics(){const live=state.jobs.filter(j=>j.body.mode==='live'),rated=live.filter(j=>j.review&&j.review.verdict!=='pending'),passed=rated.filter(j=>j.review.verdict==='pass'),unknown=live.filter(j=>j.actual===null),spend=live.reduce((s,j)=>s+(j.actual??0),0);return {live,rated,passed,unknown,spend}}
function renderJobs(){const v=metrics(),q=state.filters.jobQuery||'',mode=state.filters.jobMode||'all',kind=state.filters.jobKind||'all';const jobs=state.jobs.filter(j=>(mode==='all'||j.body.mode===mode)&&(kind==='all'||j.body.kind===kind)&&`${j.body.label} ${j.body.group} ${j.body.model_id} ${j.body.model_snapshot.name} ${j.body.resolution} ${j.id}`.toLowerCase().includes(q.toLowerCase()));$('#main').innerHTML=heading('EXPERIMENT NOTEBOOK','每一次测试，都有迹可循。','选定规格、实际文件、模板版本与核对费用分别记录。',`<a class="button" href="/api/export?format=csv">导出 CSV</a><a class="button" href="/api/export?format=json">导出 JSON</a>`)+`<div class="grid4"><div class="metric"><small>真实调用记录</small><strong>${v.live.length}</strong><p>模拟任务单独标记</p></div><div class="metric"><small>人工合格率</small><strong>${v.rated.length?Math.round(v.passed.length/v.rated.length*100)+'%':'—'}</strong><p>${v.rated.length} 条已评价真实结果</p></div><div class="metric"><small>已登记模型费用</small><strong>${money(v.spend)}</strong><p>${v.unknown.length} 条待核对；含按用量计算金额</p></div><div class="metric"><small>每条合格结果成本</small><strong>${!v.unknown.length&&v.passed.length?money(v.spend/v.passed.length):'—'}</strong><p>包含失败费用与计算金额</p></div></div><div class="toolbar"><input id="job-search" placeholder="搜索实验、模型、清晰度或对照组" value="${esc(q)}" aria-label="搜索任务"><select id="job-mode" aria-label="执行模式">${[['all','全部模式'],['live','真实调用'],['mock','模拟测试']].map(([k,n])=>`<option value="${k}" ${k===mode?'selected':''}>${n}</option>`).join('')}</select><select id="job-kind" aria-label="生成类型">${[['all','图片与视频'],['image','图片'],['video','视频']].map(([k,n])=>`<option value="${k}" ${k===kind?'selected':''}>${n}</option>`).join('')}</select></div>`+(jobs.length?`<div class="table-wrap"><table><thead><tr><th>实验 / 时间</th><th>模型与生成规格</th><th>状态 / 评价</th><th>费用与计费用量</th><th>操作</th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${esc(j.body.label||j.id.slice(0,8))}<br><span class="muted">${date(j.created)}<br>${esc(j.body.group||'未分组')}</span></td><td>${jobTags(j)}</td><td>${badge(j.state)}<p>${j.review?.verdict==='pass'?'合格':j.review?.verdict==='fail'?'不合格':'待评价'}</p>${scoreRow(j)}</td><td><div class="cost-detail">${costSummary(j)}</div></td><td><button class="text-button" data-job="${j.id}">详情 / 评分 ↗</button></td></tr>`).join('')}</tbody></table></div>`:empty('jobs','没有符合条件的测试记录','调整筛选或从创作台创建任务。'))}
function renderCompare(){const kind=state.filters.compareKind||'all';const candidates=state.jobs.filter(j=>j.outputs?.length&&(kind==='all'||j.body.kind===kind));const selected=state.compare.map(id=>state.jobs.find(j=>j.id===id)).filter(Boolean);$('#main').innerHTML=heading('SIDE BY SIDE','把差异，放在一起看。','先预览候选素材，再加入对比。比较规格、质量与交付成本。')+`<section class="card"><div class="compare-tools"><select id="compare-kind" aria-label="对比素材类型">${[['all','图片与视频'],['image','图片'],['video','视频']].map(([k,n])=>`<option value="${k}" ${kind===k?'selected':''}>${n}</option>`).join('')}</select><select id="compare-select" aria-label="选择对比结果"><option value="">选择结果，先预览…</option>${candidates.map(j=>`<option value="${j.id}" ${state.compareCandidate===j.id?'selected':''}>${esc(j.body.label||j.body.model_snapshot.name)} · ${esc(j.body.resolution)}${j.body.kind==='video'?` · ${j.body.duration}s`:''} · ${money(j.actual)} · ${date(j.created)}</option>`).join('')}</select>${loopControl()}<button class="button" data-action="clear-compare">清空对比</button></div><div id="compare-candidate" class="candidate-preview"></div></section><div class="notice">最多对比4条。模拟结果不计入质量排名；选定规格与实际文件分开标记。单张首帧无法验证背面真实细节。</div>`+(selected.length?`<div class="compare-grid">${selected.map(j=>`<article class="card compare-card"><div class="asset-image">${media(asset(j.outputs[0]),'',true)}</div><h3>${esc(j.body.label||j.body.model_snapshot.name)}</h3>${jobTags(j)}<p class="small-note">${esc(j.body.model_snapshot.model)} · ${esc(j.body.group||'未分组')}</p>${scoreRow(j)}<div class="cost-detail">${costSummary(j)}</div><p class="small-note">问题 ${esc((j.review?.issues||[]).join('、')||'未标记')}<br>${esc(j.review?.notes||'')}</p><div class="row-actions"><button class="button small" data-job="${j.id}">查看与评分</button><button class="button small" data-remove-compare="${j.id}">移除</button><a class="button small" href="${esc(asset(j.outputs[0])?.download_url)}">下载</a></div></article>`).join('')}</div>`:empty('compare','选择结果，开始对比','预览候选后点击加入对比。'));compareCandidate()}
function renderSettings(){$('#main').innerHTML=heading('PROVIDERS & CONNECTIONS','模型可以换，工作流由我们掌握。','凭证只在服务器保存。配置状态不代表权限、余额或效果已经实测。')+`<div class="studio-grid"><section class="card"><div class="card-head"><h2>国内平台连接</h2><span class="pill ${state.boot.live_enabled?'orange':'neutral'}">${state.boot.live_enabled?'真实调用已开启':'仅模拟模式'}</span></div>${state.boot.providers.map(p=>`<div class="provider-row"><div class="provider-icon">${esc(p.name[0])}</div><div><h3>${esc(p.name)}</h3><p>${esc(p.base)}<br>服务器变量 ${p.key_env}</p></div><span class="pill ${p.configured?'green':'neutral'}">${p.configured?'Key 已配置':'待配置'}</span></div>`).join('')}<div class="notice">在服务器的 .env 中填写 Key，重启服务后生效。网页不会读取或保存完整 Key。图片可按接口内联；视频/音频一般由供应商访问公网签名URL，不需要模型Key发到网页。</div></section><section class="card"><h2>调用边界</h2><div class="provider-row"><div><h3>每日预算预占</h3><p>上海时区每日重置 · 未核对费用保留预占</p></div><span class="pill orange">${money(state.boot.daily_budget)}</span></div><div class="provider-row"><div><h3>每日真实任务上限</h3><p>每个新任务只提交一次生成请求</p></div><span class="pill neutral">${state.boot.daily_call_limit} 次</span></div><p class="hint">本站限额控制新增任务。上游计费、审核失败和超时可能产生费用，请同时设置供应商侧额度。</p><a class="button small" href="#jobs">查看费用记录 ↗</a></section></div><div class="card workflow-card"><div class="card-head"><h2>模型能力档案</h2><span class="pill neutral">核对日期 2026-09-30</span></div><div class="table-wrap"><table><thead><tr><th>模型</th><th>输入模式</th><th>素材能力</th><th>规格 / 刊例价格</th><th>接入状态</th><th>资料</th></tr></thead><tbody>${state.boot.models.map(m=>`<tr><td>${esc(providerName(m.provider))}<br>${esc(m.name)}<br><span class="muted">${esc(m.model)}</span></td><td>${Object.values(m.modes).map(x=>esc(x.label)).join(' / ')}</td><td>图片 ≤${m.max_images}${m.video_max?'<br>视频 ≤'+m.video_max+'秒':''}${m.audio_max?'<br>音频 ≤'+m.audio_max+'秒':''}</td><td>${esc(m.resolutions.join(' / '))}<br>${m.durations.length?`${m.durations[0]}～${m.durations.at(-1)}s`:'跟随输入 / 上游固定'}<br>${esc(priceInfo(m))}</td><td>${esc(m.verified)} / 待真实验证</td><td><a href="${esc(m.docs)}" target="_blank" rel="noreferrer">官方文档 ↗</a></td></tr>`).join('')}</tbody></table></div></div>`}
function dialog(title,content,actions=''){ $('#dialog-body').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-button" data-close aria-label="关闭">×</button></div><div class="dialog-content">${content}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!$('#dialog').open)$('#dialog').showModal();}
function closeDialog(){$('#dialog').close()}
function picker(){const library=state.route!=='studio',kinds=library?['image','video','audio','file']:inputKinds().filter(canAddKind);const formats={image:'.jpg,.jpeg,.png,.webp',video:'.mp4,.mov',audio:'.mp3,.wav',file:'.pdf,.txt,.md,.docx,.xlsx,.pptx'};const capacity=library||state.draft.reference_board?50:Object.entries(currentModel().modes[state.draft.video_mode].limits).reduce((n,[u,max])=>n+Math.max(0,max-(inputCheck().counts[u]||0)),0);dialog('添加你的素材',`<label class="upload-zone" id="drop-zone">${icon('upload')}<h3>选择文件，或拖放到这里</h3><p>${library?'上传到素材库，独立保存':'仅接受当前模式允许的类型与数量'} · ≤200MB</p><input id="upload-input" type="file" accept="${kinds.map(k=>formats[k]).filter(Boolean).join(',')}" ${capacity>1?'multiple':''} class="hidden"></label><div class="field upload-origin"><label for="upload-origin">本次上传来源（由上传者标记）</label><select id="upload-origin"><option value="self">本人上传</option><option value="user">用户提供的素材</option></select></div><p class="hint">${library?'上传后可在素材库选择加入任务。':'首尾帧将依次分配到独立位置；名额已满或不兼容的素材不可加入。'}</p><div class="picker-grid">${state.assets.map(a=>{const reason=refProposal({asset_id:a.id,role:a.kind==='image'?'look':'motion'}).error;return `<button class="pick" data-pick="${a.id}" ${reason?'disabled':''} title="${esc(reason||'加入当前任务')}">${media(a)}<p>${esc(a.name)}</p>${reason?`<small>${esc(reason)}</small>`:''}</button>`}).join('')}</div>`);const z=$('#drop-zone');z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('drag')});z.addEventListener('dragleave',()=>z.classList.remove('drag'));z.addEventListener('drop',async e=>{e.preventDefault();await uploadFiles(e.dataTransfer.files)});}
function addReference(ref){const next=refProposal(ref);if(next.error){toast(next.error,true);return false}state.draft.refs.push(next.ref);state.draft.image_confirmed=false;return true;}
function addRef(a){if(!a)return false;let role=a.kind==='audio'?'audio':a.kind==='file'?'document':a.kind==='video'?'motion':state.draft.kind==='video'||currentModel().adapter==='mini_image'?'look':['upper','lower','shoes'].find(r=>!state.draft.refs.some(x=>x.role===r))||'accessory';return addReference({asset_id:a.id,role});}
function preflightFiles(files){if(state.route!=='studio')return;const refs=[...state.draft.refs],pending={};for(const [i,f] of [...files].entries()){const ext=f.name.split('.').pop().toLowerCase(),kind=/^(jpg|jpeg|png|webp)$/.test(ext)?'image':/^(mp4|mov)$/.test(ext)?'video':/^(mp3|wav)$/.test(ext)?'audio':/^(pdf|txt|md|docx|xlsx|pptx)$/.test(ext)?'file':'unknown';const id='pending-'+i;pending[id]={kind,size:f.size,duration:currentModel()[kind+'_min']||1};const next=refProposal({asset_id:id,role:kind==='image'?'look':kind==='audio'?'audio':'motion'},{...state.draft,refs},id=>pending[id]||asset(id));if(next.error)throw Error(next.error);refs.push(next.ref);}}
async function uploadFiles(files){const z=$('#drop-zone');try{preflightFiles(files);if(z)z.classList.add('busy');let added=0;for(const f of files){const form=new FormData();form.append('file',f);form.append('origin',$('#upload-origin')?.value||'self');const a=await api('/assets',{method:'POST',body:form});state.assets.unshift(a);if(state.route==='studio'&&addRef(a))added++;}closeDialog();render();toast(state.route==='studio'?`素材已保存；${added}件加入当前任务，其他素材可在素材库查看`:'素材已上传并保存')}catch(e){toast(e.message,true);if(z)z.classList.remove('busy')}}
function getPayload(){const checked=inputCheck();if(checked.errors.length||checked.missing.length)throw Error(checked.errors[0]?.message||checked.missing[0]);const d={...state.draft,refs:state.draft.refs.map(r=>({...r})),template_version:currentTemplate()?.version};for(const k of ['seed','duration','max_cost'])d[k]=Number(d[k]);return d;}
function chooseTemplate(id){state.draft.template_id=id;state.draft.prompt_override='';if(id==='full-turn-360'){const durations=WardrobeInputs.parameters(currentModel(),state.draft,asset).duration||[];state.draft.duration=durations.find(v=>v>=8&&v<=15)||durations.at(-1)||state.draft.duration;}}
function setKind(kind){if(kind===state.draft.kind)return;state.draft.kind=kind;state.draft.model_id=kind==='image'?'seedream':'wan-flash';state.draft.template_id=kind==='image'?'studio-front':'gentle-turn';state.draft.prompt_override='';state.draft.reference_board=false;state.draft.image_confirmed=false;state.draft.resolution=currentModel().resolutions[0];state.draft.duration=currentModel().durations[0]||3;state.draft.video_mode=currentModel().default_mode;state.draft.audio_mode=currentModel().audio_options[0];state.draft.refs=WardrobeInputs.reconcile(currentModel(),state.draft,asset);renderStudio();}
async function generate(){if(creating)return;creating=true;const button=$('[data-action="generate"]');if(button){button.disabled=true;button.textContent='正在提交…'}try{const payload=getPayload(),encoded=JSON.stringify(payload);if(lastPayload!==encoded){submittingId=WardrobeInputs.requestId();lastPayload=encoded}const j=await api('/jobs',{method:'POST',headers:{'Idempotency-Key':submittingId},body:encoded});lastPayload=null;submittingId=null;state.activeJob=j.id;await loadData();toast(payload.mode==='mock'?'模拟任务已创建':'真实任务已创建，后台执行中');}catch(e){toast(e.message,true)}finally{creating=false;renderStudio();}}
async function preview(){try{const p=await api('/preview',{method:'POST',body:JSON.stringify(getPayload())});dialog('本次请求预览',`<div class="timeline-summary">${p.stages.map(x=>`<span class="pill neutral">${esc(x)}</span>`).join('')}</div><p class="small-note">${p.estimate.estimated_cny===null?'参考价格待核对':`预计模型费用 ${money(p.estimate.estimated_cny)}`} · ${esc(p.estimate.source)}</p><p class="hint">刊例参考 ${money(p.estimate.reference_cny)} · ${esc(p.estimate.confidence)}<br>${esc((p.estimate.breakdown||[]).join('；'))}<br>${esc(p.estimate.discount_note)}<br>${esc(p.estimate.note)}</p><div class="code">${esc(JSON.stringify(p.request,null,2))}</div>${p.warnings.map(w=>`<p class="hint">${esc(w)}</p>`).join('')}`,`<button class="button" data-close>返回修改</button>`)}catch(e){toast(e.message,true)}}
async function jobDialog(id){try{const j=await api('/jobs/'+id),r=j.review||{};state.reviewContext=j.billing_context;state.reviewMock=j.body.mode==='mock';state.receiptMode=r.billing_mode||'amount';const videoFrom=j.body.kind==='image'&&r.verdict==='pass'&&j.outputs.length;dialog('实验详情与质量评估',`<div class="timeline-summary">${badge(j.state)}<span class="pill neutral">${j.body.mode==='mock'?'模拟 · 零模型费用':'真实调用'}</span><span class="pill neutral">${esc(j.body.model_snapshot.name)}</span></div>${jobTags(j)}${loopControl()}<div class="cost-detail">${costSummary(j)}</div>${j.error?`<div class="notice">${esc(j.error)}</div>`:''}${j.outputs.map(aid=>`<div class="asset-image">${media(asset(aid),'',true)}</div><a class="button small" href="${esc(asset(aid)?.download_url)}">下载原始结果</a>`).join('')}<p class="hint">任务 ${j.id}<br>供应商任务 ${esc(j.provider_task_id||'尚未取得')}<br>提示词 ${esc(j.body.prompt_version)} · 模板 v${j.body.template_version}</p><div class="events">${j.events.map(e=>`<div class="event">${esc(e.message)}<small>${esc(e.stage)} · ${date(e.created)}</small></div>`).join('')}</div>
 ${['uncertain','paused','save_failed'].includes(j.state)?`<div class="inline-form"><input id="resume-id" class="dialog-input" placeholder="供应商任务编号（仅待核对时需要）" value="${esc(j.provider_task_id||'')}"><button class="button" data-resume="${j.id}">${j.state==='save_failed'?'重试保存':'恢复查询'}</button></div>`:''}
 <h3>人工评价与账单核对</h3><p class="hint">API成功只代表生成完成；印花改变、漏单品或明显变脸应判为不合格。失败任务也要记录实际费用。</p><form id="review-form" data-jid="${j.id}"><div class="review-form">${['clothing','identity',...(j.body.kind==='video'?['motion']:[])].map((k,i)=>`<div class="field"><label>${['服装保真','身份一致','动作表现'][i]}</label><select name="${k}">${options([1,2,3,4,5],r[k]||3)}</select></div>`).join('')}<div class="field"><label>交付结论</label><select name="verdict">${[['pending','待评价'],['pass','合格'],['fail','不合格']].map(([k,v])=>`<option value="${k}" ${r.verdict===k?'selected':''}>${v}</option>`).join('')}</select></div>${[ ["background","白底一致"],["framing","构图完整"],["detail","清晰度 / 细节"] ].map(([k,n])=>`<div class="field"><label>${n}</label><select name="${k}"><option value="">待评价</option>${options([1,2,3,4,5],r[k]||'')}</select></div>`).join('')}${billingFields(j)}<div class="field full"><label>问题标签（逗号分隔）</label><input name="issues" value="${esc((r.issues||[]).join(','))}" placeholder="可点选标签，也可填写其他问题">${issueButtons(j)}</div><div class="field full"><label>评价备注</label><textarea name="notes">${esc(r.notes||'')}</textarea></div></div><div class="submit-row"><button class="button primary" type="submit">保存评分与账单</button></div></form><details><summary class="small-note">输入、配置与用量记录</summary><div class="code">${esc(JSON.stringify({input:j.body,usage:j.usage},null,2))}</div></details>`,`${videoFrom?`<button class="button primary" data-video-from="${j.outputs[0]}">生成动态展示</button>`:''}<button class="button" data-close>关闭</button>`);updateBilling()}catch(e){toast(e.message,true)}}
function templateDialog(id){const t=state.boot.templates.find(x=>x.id===id)||{id:'custom-look',name:'我的新模板',kind:'image',category:'outfit_image',description:'纯白背景展示',prompt:'背景与地面统一为纯白色（#FFFFFF），无场景、杂物、渐变和舞台光。人物全身居中，头顶和鞋底留白，固定水平镜头。保留衣服颜色、图案、轮廓及人物身份。',negative_prompt:'非白背景、背景杂物、切镜、身份漂移、服装改变、头脚截断',criteria:['纯白背景','服装保真','全身完整入镜']};dialog(id==='new'?'新建模板':'编辑模板 · 保存为新版本',`<form id="template-form"><div class="form-grid"><div class="field"><label>模板 ID（英文短横线）</label><input name="id" value="${esc(t.id)}" required ${id!=='new'?'readonly':''}></div><div class="field"><label>名称</label><input name="name" value="${esc(t.name)}" required></div><div class="field"><label>类型</label><select name="kind">${options(['image','video'],t.kind)}</select></div><div class="field"><label>技能</label><select name="category">${options(['outfit_image','garment_present','outfit_video'],t.category)}</select></div><div class="field full"><label>描述</label><input name="description" value="${esc(t.description)}"></div><div class="field full"><label>正向提示词</label><textarea name="prompt" required>${esc(t.prompt)}</textarea></div><div class="field full"><label>避免项（会附加到提示词）</label><textarea name="negative_prompt">${esc(t.negative_prompt)}</textarea></div><div class="field full"><label>验收标准（每行一条）</label><textarea name="criteria">${esc(t.criteria.join('\n'))}</textarea></div></div><div class="notice">每次保存创建新版本。已创建的任务保留旧版模板、素材与模型快照。</div><button class="button primary" type="submit">保存新版本</button></form>`)}
async function confirmDelete(aid){const a=asset(aid);dialog('删除素材',`<p class="small-note">删除「${esc(a.name)}」的服务器文件。已被任务引用的素材会保留，需先处理相关测试记录。</p>`,`<button class="button" data-close>取消</button><button class="button danger" data-confirm-delete="${aid}">删除素材</button>`)}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el||el.disabled)return;try{
 if(el.hasAttribute('data-close'))return closeDialog();
 if(el.dataset.issue){const input=$('#review-form [name=issues]'),items=input.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean),found=items.includes(el.dataset.issue);input.value=(found?items.filter(x=>x!==el.dataset.issue):[...items,el.dataset.issue]).join(', ');el.classList.toggle('selected',!found);return;}
 if(el.dataset.kind)return setKind(el.dataset.kind);
 if(el.dataset.template){chooseTemplate(el.dataset.template);return renderStudio()}
 if(el.dataset.removeRef!==undefined){state.draft.refs.splice(Number(el.dataset.removeRef),1);state.draft.image_confirmed=false;return renderStudio()}
 if(el.dataset.pick){if(!addRef(asset(el.dataset.pick)))return;closeDialog();if(state.route!=='studio'){location.hash='studio'}else renderStudio();return toast('已加入素材，请确认它的角色')}
 if(el.dataset.useAsset){if(!addRef(asset(el.dataset.useAsset)))return;location.hash='studio';return}
 if(el.dataset.deleteAsset)return confirmDelete(el.dataset.deleteAsset);
 if(el.dataset.confirmDelete){await api('/assets/'+el.dataset.confirmDelete,{method:'DELETE'});await loadData();closeDialog();render();return toast('素材已删除')}
 if(el.dataset.job)return jobDialog(el.dataset.job);
 if(el.dataset.resume){await api('/jobs/'+el.dataset.resume+'/resume',{method:'POST',body:JSON.stringify({provider_task_id:$('#resume-id').value})});await loadData();await jobDialog(el.dataset.resume);return toast('仅恢复查询或保存，不重新生成')}
 if(el.dataset.videoFrom){setKind('video');state.draft.refs=[];addRef(asset(el.dataset.videoFrom));state.draft.image_confirmed=true;state.draft.mode=state.jobs.find(j=>j.outputs.includes(el.dataset.videoFrom))?.body.mode||'mock';state.activeJob=null;closeDialog();location.hash='studio';renderStudio();return}
 if(el.dataset.editTemplate)return templateDialog(el.dataset.editTemplate);
 if(el.dataset.templateUse){const t=state.boot.templates.find(x=>x.id===el.dataset.templateUse);setKind(t.kind);chooseTemplate(t.id);location.hash='studio';return renderStudio()}
 if(el.dataset.addCompare){if(state.compare.length>=4)return toast('最多同时对比4条',true);if(!state.compare.includes(el.dataset.addCompare))state.compare.push(el.dataset.addCompare);return renderCompare()}
 if(el.dataset.removeCompare){state.compare=state.compare.filter(x=>x!==el.dataset.removeCompare);return renderCompare()}
 const action=el.dataset.action;
 if(action==='picker')return picker();if(action==='external')return externalDialog();
 if(action==='demo'){const rows=await api('/demo',{method:'POST',body:'{}'});await loadData();rows.forEach(x=>{if(!state.draft.refs.some(r=>r.asset_id===x.asset.id)&&state.draft.kind==='image')addReference({asset_id:x.asset.id,role:x.role})});render();return toast('示例插画已载入；仅用于流程验证')}
 if(action==='reset-prompt'){state.draft.prompt_override='';return renderStudio()}
 if(action==='generate')return generate();
 if(action==='preview')return preview();
 if(action==='clear-compare'){state.compare=[];return renderCompare()}
 }catch(err){toast(err.message,true)}});
document.addEventListener('input',e=>{if(e.target.closest('#review-form')&&['actual_cny','billed_units','rate_override','rate_note'].includes(e.target.name)){clearTimeout(billingTimer);++billingSequence;billingTimer=setTimeout(updateBilling,250)}const k=e.target.dataset.field;if(k&&e.target.tagName!=='SELECT'&&e.target.type!=='checkbox')state.draft[k]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(e.target.dataset.refKey&&e.target.tagName!=='SELECT')state.draft.refs[Number(e.target.dataset.refIndex)][e.target.dataset.refKey]=e.target.value;});
document.addEventListener('change',async e=>{const el=e.target,k=el.dataset.field;
 if(k){state.draft[k]=el.type==='checkbox'?el.checked:el.value;if(k==='model_id'){const m=currentModel();state.draft.resolution=m.resolutions[0];state.draft.duration=m.durations[0]||3;state.draft.video_mode=m.default_mode;state.draft.audio_mode=m.audio_options[0];if(!m.ratios.includes(state.draft.ratio))state.draft.ratio=m.ratios[0];state.draft.refs=WardrobeInputs.reconcile(m,state.draft,asset);state.draft.image_confirmed=false;renderStudio()}else if(k==='video_mode'){state.draft.resolution=currentModel().modes[el.value].resolutions?.[0]||currentModel().resolutions[0];state.draft.duration=currentModel().modes[el.value].durations?.[0]||currentModel().durations[0]||3;state.draft.refs=WardrobeInputs.reconcile(currentModel(),state.draft,asset);state.draft.image_confirmed=false;renderStudio()}else if(['mode','reference_board','resolution','duration','audio_mode','image_confirmed','identity_consent','paid_confirmed','person_mode'].includes(k))renderStudio();}
 if(el.dataset.refKey){state.draft.refs[Number(el.dataset.refIndex)][el.dataset.refKey]=el.value;state.draft.image_confirmed=false;renderStudio();}
 if(el.dataset.roleIndex!==undefined){state.draft.refs[Number(el.dataset.roleIndex)].role=el.value;state.draft.image_confirmed=false;renderStudio();}
 if(el.id==='upload-input')return uploadFiles(el.files);
 if(el.id==='asset-kind'){state.filters.assetKind=el.value;renderAssets()}
 if(el.id==='job-mode'){state.filters.jobMode=el.value;renderJobs()}
 if(el.id==='compare-select'){state.compareCandidate=el.value;compareCandidate()}
 if(el.id==='compare-kind'){state.filters.compareKind=el.value;state.compareCandidate='';renderCompare()}
 if(el.id==='asset-source'){state.filters.assetSource=el.value;renderAssets()}
 if(el.id==='job-kind'){state.filters.jobKind=el.value;renderJobs()}
 if(el.hasAttribute('data-loop')){state.loopVideos=el.checked;$$('video[controls]').forEach(v=>v.loop=state.loopVideos);$$('[data-loop]').forEach(x=>x.checked=state.loopVideos)}
 if(el.closest('#review-form')&&['billing_mode','billing_unit'].includes(el.name)){const f=el.closest('form');if(el.name==='billing_mode'){if(state.receiptMode==='amount')f.elements.billed_units.value='';if(state.receiptMode==='units')f.elements.actual_cny.value='';state.receiptMode=el.value;}updateBilling();}
});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='asset-search'){state.filters.assetQuery=e.target.value;renderAssets()}if(e.key==='Enter'&&e.target.id==='job-search'){state.filters.jobQuery=e.target.value;renderJobs()}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,formId=f.getAttribute('id');try{if(formId==='login-form'){const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:$('#password').value})});const d=await r.json();if(!r.ok)throw Error(d.detail);$('#password').value='';await boot();}
 if(formId==='external-form'){const d=Object.fromEntries(new FormData(f));const ref={role:d.vendor_kind==='video'?'motion':d.vendor_kind==='audio'?'audio':'look',usage:'auto',vendor_kind:d.vendor_kind,vendor_active:!!d.vendor_active,trusted_original:!!d.trusted_original};if(d.duration)ref.duration=Number(d.duration);ref[d.source==='id'?'vendor_asset_id':'url']=d.value.trim();if(!addReference(ref))return;closeDialog();renderStudio();toast('已加入并分配接口用途')}
 if(formId==='review-form'){const d=Object.fromEntries(new FormData(f));for(const k of ['clothing','identity','motion','background','framing','detail'])d[k]=d[k]===''||d[k]===undefined?null:Number(d[k]);Object.assign(d,receiptPayload(f));d.issues=d.issues.split(/[,，]/).map(x=>x.trim()).filter(Boolean);await api('/jobs/'+f.dataset.jid+'/review',{method:'POST',body:JSON.stringify(d)});await loadData();closeDialog();render();toast('评价与费用记录已保存')}
 if(formId==='template-form'){const d=Object.fromEntries(new FormData(f));d.criteria=d.criteria.split('\n').filter(Boolean);await api('/templates',{method:'POST',body:JSON.stringify(d)});state.boot=await api('/bootstrap');closeDialog();render();toast('模板新版本已保存')}
 }catch(err){if(formId==='login-form')$('#login-error').textContent=err.message;else toast(err.message,true)}});
$('#menu-toggle').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));
$('#refresh').addEventListener('click',async()=>{try{await loadData();state.boot=await api('/bootstrap');render();toast('已刷新')}catch(e){toast(e.message,true)}});
$('#logout').addEventListener('click',async()=>{try{await api('/logout',{method:'POST',body:'{}'});showLogin()}catch(e){toast(e.message,true)}});
window.addEventListener('hashchange',route);
setInterval(async()=>{if(!state.boot||$('#shell').classList.contains('hidden')||refreshBusy||document.hidden)return;refreshBusy=true;try{await loadData();$('#connection').innerHTML='<i class="status-dot"></i> 已连接';if(state.route==='studio'){updatePreview();updateRecent()}else if(state.route==='jobs'&&!$('#dialog').open&&!document.activeElement.matches('input,select'))renderJobs();}catch{ $('#connection').textContent='连接暂时中断';}finally{refreshBusy=false}},3000);
boot();
